Amazon API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "Amazon API Gateway") {
    Component(Edge_Request_Router, "Edge Request Router", "Amazon API Gateway", "Routes incoming HTTPS and REST requests from the React SPA to appropriate backend services.")
    Component(Auth_Authorizer, "Auth & Authorizer", "AWS Lambda", "Handles authentication and authorization for incoming client requests.")
    Component(Rate_Limiter, "Rate Limiter", "Amazon API Gateway", "Enforces rate limiting to protect backend services from excessive traffic.")
    Component(GraphQL_Proxy, "GraphQL Proxy", "AWS AppSync / Amazon API Gateway", "Proxies GraphQL requests from the client to the underlying microservices.")
}

Rel(Edge_Request_Router, Auth_Authorizer, "Validates request tokens")
Rel(Edge_Request_Router, Rate_Limiter, "Checks request quotas")
Rel(Edge_Request_Router, GraphQL_Proxy, "Forwards GraphQL queries")

@enduml

Amazon RDS (PostgreSQL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon RDS (PostgreSQL) container

Container_Boundary(amazon_rds_postgresql, "Amazon RDS (PostgreSQL)") {
    Component(ConnectionPooler, "Connection Pooler", "PgBouncer", "Manages database connections to prevent connection exhaustion.")
    Component(RelationalStorageEngine, "Relational Storage Engine", "PostgreSQL 15", "ACID-compliant transactional data storage for catalogs, orders, and PII.")
    Component(BackupReplicationManager, "Backup & Replication Manager", "AWS Backup / Amazon S3", "Manages encrypted snapshot exports and replication across regions.")
}

Rel(ConnectionPooler, RelationalStorageEngine, "Internal TCP socket")
Rel(BackupReplicationManager, RelationalStorageEngine, "Encrypted snapshot exports [AWS KMS, TLS 1.3]")

@enduml

Amazon EventBridge, SQS, SNS.diagram:
